head.script:
scwin.fn_GetPar, scwin.fn_SetPar;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        $c.bns.BnsPanelToGroupBox(pnl_List); // 패널라운드처리
        // 파라미터추출
        const prt = $c.frame.path("../");
        if (prt !== undefined) {
            scwin.fn_GetPar = prt.scwin.fn_GetPar;
            scwin.fn_SetPar = prt.scwin.fn_SetPar;
        }
        if (scwin.fn_GetPar !== undefined) {
            let arrPar = new Array();
            scwin.fn_GetPar(arrPar);
            url += "&service=krx.lds.stf.listingcommon.services.ListingCommonApp";
            url += "&outputMessageId=BNS_DELIST_RSN_SEL";
            url += "&queryId=lds.stf.bnsisuchg.select.listDelistRsn";
            url += "&SCREN_ID=" + "ULDBNS11201.xml";
            url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
            const sbmOptions = {
                id : "sbm_dts_List",
                action : "/listingCommon.do",
                ref : "",
                target : "dts_List=body.content",
                isProcessMsg : false
            };

            const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
            // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS11201.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name dts_List_OnLoadError
 * @description dts_List 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_List_OnLoadError = async function() {
    try {
        await $c.win.alert($c.stf.getMessageParam("MSG-0002"));
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS11201.dts_List_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_List_OnLoadCompleted
 * @description dts_List 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_List_OnLoadCompleted = function(rowcount) {
    try {
        txb_TotalCnt.setValue("총 " + rowcount + "건");
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS11201.dts_List_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name grd_List_OnDblClick
 * @description grd_List 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_List_OnDblClick = async function(row, colid) {
    try {
        const gDelistCd = dts_List.getCellData(row, "BND_DELIST_CD");
        const gActivYn = dts_List.getCellData(row, "ACTIV_YN");
        if (await scwin.clickDataCheck(gDelistCd) === false) return;
        if (!await scwin.checkActiv(gActivYn)) return;
        let arrPar = new Array();
        arrPar[0] = {
            BND_DELIST_CD: gDelistCd,
            DELIST_RSN_DTL: dts_List.getCellData(row, "DELIST_RSN_DTL"),
            MEMO: dts_List.getCellData(row, "MEMO")
        };
        scwin.fn_SetPar(arrPar);
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS11201.grd_List_OnDblClick" });
    }
};

/**
 * @method
 * @name btn_Close_onclick
 * @description 「닫기」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Close_onclick = async function() {
    try {
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS11201.btn_Close_onclick" });
    }
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name clickDataCheck
 * @description click Data Check 처리
 * @param {String} vDelistCd vDelistCd
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.clickDataCheck = async function(vDelistCd) {
    if (vDelistCd === 01 || vDelistCd === 02) {
        await $c.win.alert("만기상환이나 전액중도상환은 자동 상장폐지로 처리됩니다. 다시 선택하십시오.");
        return false;
    }
    return true;
};

/**
 * @method
 * @name checkActiv
 * @description check Activ 처리
 * @param {*} ACTIV_YN ACTIV_YN
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkActiv = async function(ACTIV_YN) {
    if (ACTIV_YN === 'N') {
        let output = '비활성화된 코드입니다. ';
        output += '\n' + '활성 <-> 비활성 변경시 시스템관리자에게 직접 연락하세요';
        await $c.win.alert(output);
        return false;
    }
    return true;
};
